/* ============================================================
   AgendaBot :: Helpers comunes (sin dependencias externas)
   Zona horaria fija: America/Bogota (UTC-5, sin horario de verano)
   ============================================================ */
const TZ_OFFSET_MS = -5 * 60 * 60 * 1000;
function pad(n, l) { return String(n).padStart(l, '0'); }
function ahora() { return new Date(Date.now() + TZ_OFFSET_MS); }
function aFechaISO(d) { return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1, 2) + '-' + pad(d.getUTCDate(), 2); }
function aHoraHM(d) { return pad(d.getUTCHours(), 2) + ':' + pad(d.getUTCMinutes(), 2); }
function hoyISO() { return aFechaISO(ahora()); }
function horaActual() { return aHoraHM(ahora()); }
function timestampCO() { const d = ahora(); return aFechaISO(d) + ' ' + aHoraHM(d) + ':' + pad(d.getUTCSeconds(), 2); }
function sumarDias(f, n) {
  const p = String(f).split('-').map(Number);
  return aFechaISO(new Date(Date.UTC(p[0], p[1] - 1, p[2] + n)));
}
function esFechaValida(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s || ''))) return false;
  const p = String(s).split('-').map(Number);
  if (p[1] < 1 || p[1] > 12) return false;
  const diasMes = new Date(Date.UTC(p[0], p[1], 0)).getUTCDate();
  return p[2] >= 1 && p[2] <= diasMes && p[0] >= 2000 && p[0] <= 2100;
}
function esHoraValida(s) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s || '')); }
function esPasado(f, h) {
  const hoy = hoyISO();
  if (f < hoy) return true;
  if (f === hoy && h && h <= horaActual()) return true;
  return false;
}
function vacio(s) { return String(s == null ? '' : s).trim().length === 0; }
function limpiar(s) { return String(s == null ? '' : s).trim().replace(/\s+/g, ' ').slice(0, 200); }
function filasReales(items, clave) {
  return items.map(function (i) { return i.json; })
              .filter(function (r) { return r && r[clave] != null && String(r[clave]).trim() !== ''; });
}
function siguienteId(filas, campo, prefijo) {
  let max = 0;
  for (const r of filas) {
    const m = String(r[campo] || '').match(/(\d+)\s*$/);
    if (m) { const n = parseInt(m[1], 10); if (n > max) max = n; }
  }
  return prefijo + '-' + pad(max + 1, 3);
}
function leerDatos(t) { try { const o = JSON.parse(t || '{}'); return (o && typeof o === 'object') ? o : {}; } catch (e) { return {}; } }
function esVerdadero(v) {
  const s = String(v == null ? '' : v).trim().toUpperCase();
  return s === 'TRUE' || s === 'VERDADERO' || s === 'SI' || s === 'SÍ' || s === '1' || s === 'X' || s === 'YES';
}
const PIE = '\n————————\n9 Volver   ·   /menu Menú principal   ·   /cancelar Cancelar';
function opcionInvalida(extra) {
  return '⚠️ No entendí esa opción.\n' + (extra || 'Escribe únicamente el número de una de las opciones mostradas.');
}
function salida(mensaje, pantalla, paso, datos, resultado, accion, fila) {
  return [{ json: {
    mensaje: String(mensaje).slice(0, 3900),
    pantalla_nueva: pantalla,
    paso_nuevo: String(paso),
    datos_parciales: JSON.stringify(datos || {}),
    resultado: resultado || 'OK',
    accion: accion || 'NINGUNA',
    fila: fila || {}
  }}];
}

/* =====================================================================
   MODULO REPORTES (solo lectura sobre las 5 hojas de negocio)
   Pantalla: REPORTES
   ===================================================================== */
const ctx = $('▶️ Entrada Reportes').first().json;
const citas = filasReales($('📄 CITAS - Leer').all(), 'id_cita');
const tareas = filasReales($('📄 TAREAS - Leer').all(), 'id_tarea');
const habitos = filasReales($('📄 HABITOS - Leer').all(), 'id_habito');
const listas = filasReales($('📄 LISTAS - Leer').all(), 'id_lista');
const items = filasReales($input.all(), 'id_item');

const texto = String(ctx.texto || '').trim();
const usuario = String(ctx.telegram_user);
const HOY = hoyISO();

const MENU =
  '📊 REPORTES\n' +
  'Números claros sobre lo que tienes registrado.\n\n' +
  '1  Resumen general\n' +
  '2  Citas por estado\n' +
  '3  Tareas por prioridad y estado\n' +
  '4  Listas e ítems\n' +
  '9  Volver al menú principal\n\n' +
  '💡 Recomendado: 1 Resumen general\n' +
  'Tip: escribe únicamente el número.';

/* Entrada directa desde el menu principal: se muestra el menu del modulo
   sin consumir el numero que el usuario uso para entrar. */
if (ctx.entrada_modulo === true || String(ctx.entrada_modulo) === 'true')
  return salida(MENU, 'REPORTES', '0', {}, 'MENU_REPORTES');

const misCitas = citas.filter(function (c) { return String(c.creado_por || '').trim() === usuario; });
const misTareas = tareas.filter(function (t) { return String(t.creado_por || '').trim() === usuario; });
const misListas = listas.filter(function (l) { return String(l.creado_por || '').trim() === usuario; });
const idsMisListas = misListas.map(function (l) { return String(l.id_lista); });
const misItems = items.filter(function (i) { return idsMisListas.indexOf(String(i.id_lista)) !== -1; });
const habVivos = habitos.filter(function (h) { return String(h.estado || '').toUpperCase() !== 'ELIMINADO'; });

function cuenta(arr, campo) {
  const m = {};
  arr.forEach(function (r) {
    const k = String(r[campo] || 'SIN DATO').toUpperCase();
    m[k] = (m[k] || 0) + 1;
  });
  return m;
}
function pintaMapa(m, total) {
  const ks = Object.keys(m).sort();
  if (ks.length === 0) return '   (sin registros)';
  return ks.map(function (k) {
    const n = m[k];
    const pct = total > 0 ? Math.round(n * 100 / total) : 0;
    const barra = '█'.repeat(Math.max(1, Math.round(pct / 10)));
    return '   ' + k.padEnd(14, ' ') + String(n).padStart(3, ' ') + '  ' + barra + ' ' + pct + '%';
  }).join('\n');
}

if (texto === '9')
  return salida('👌 Volvamos al menú principal.\n\nEscribe /menu para verlo.',
                'MENU', '0', {}, 'VOLVER');

if (texto === '1' || texto === '') {
  const activas = misCitas.filter(function (c) {
    return ['PENDIENTE', 'REPROGRAMADA'].indexOf(String(c.estado || '').toUpperCase()) !== -1;
  });
  const abiertas = misTareas.filter(function (t) {
    return ['PENDIENTE', 'EN PROGRESO'].indexOf(String(t.estado || '').toUpperCase()) !== -1;
  });
  const itemsPend = misItems.filter(function (i) { return String(i.estado || '').toUpperCase() === 'PENDIENTE'; });
  const hoyCitas = activas.filter(function (c) { return String(c.fecha) === HOY; });
  return salida('📊 RESUMEN GENERAL   ·   ' + HOY + '\n' +
                '════════════════════════\n\n' +
                '📅 CITAS\n' +
                '   Total registradas: ' + misCitas.length + '\n' +
                '   Activas:           ' + activas.length + '\n' +
                '   Para hoy:          ' + hoyCitas.length + '\n\n' +
                '✅ TAREAS\n' +
                '   Total registradas: ' + misTareas.length + '\n' +
                '   Abiertas:          ' + abiertas.length + '\n\n' +
                '🔁 HÁBITOS\n' +
                '   Registrados:       ' + habVivos.length + '\n' +
                '   Activos:           ' + habVivos.filter(function (h) {
                    return String(h.estado || '').toUpperCase() === 'ACTIVO'; }).length + '\n\n' +
                '📝 LISTAS\n' +
                '   Listas:            ' + misListas.length + '\n' +
                '   Ítems totales:     ' + misItems.length + '\n' +
                '   Ítems pendientes:  ' + itemsPend.length + '\n\n' + MENU,
                'REPORTES', '0', {}, 'REPORTE_GENERAL');
}

if (texto === '2') {
  const m = cuenta(misCitas, 'estado');
  return salida('📅 CITAS POR ESTADO   (total ' + misCitas.length + ')\n\n' +
                pintaMapa(m, misCitas.length) + '\n\n' + MENU,
                'REPORTES', '0', {}, 'REPORTE_CITAS');
}

if (texto === '3') {
  return salida('✅ TAREAS   (total ' + misTareas.length + ')\n\n' +
                'POR PRIORIDAD\n' + pintaMapa(cuenta(misTareas, 'prioridad'), misTareas.length) + '\n\n' +
                'POR ESTADO\n' + pintaMapa(cuenta(misTareas, 'estado'), misTareas.length) + '\n\n' + MENU,
                'REPORTES', '0', {}, 'REPORTE_TAREAS');
}

if (texto === '4') {
  if (misListas.length === 0)
    return salida('📭 Todavía no tienes listas registradas.\n\n' + MENU,
                  'REPORTES', '0', {}, 'REPORTE_VACIO');
  const detalle = misListas.map(function (l) {
    const its = misItems.filter(function (i) { return String(i.id_lista) === String(l.id_lista); });
    const p = its.filter(function (i) { return String(i.estado || '').toUpperCase() === 'PENDIENTE'; }).length;
    const c = its.filter(function (i) { return String(i.estado || '').toUpperCase() === 'COMPLETADO'; }).length;
    const avance = its.length > 0 ? Math.round(c * 100 / its.length) : 0;
    return '• ' + l.nombre_lista + '  [' + l.tipo + ']\n' +
           '    ' + its.length + ' ítems · ' + p + ' pendientes · ' + c + ' completados · ' + avance + '% avance';
  }).join('\n');
  return salida('📝 LISTAS E ÍTEMS   (' + misListas.length + ' listas)\n\n' + detalle + '\n\n' + MENU,
                'REPORTES', '0', {}, 'REPORTE_LISTAS');
}

return salida(opcionInvalida('En Reportes espero 1, 2, 3, 4 o 9.') + '\n\n' + MENU,
              'REPORTES', '0', {}, 'OPCION_INVALIDA');

const r = $('🧠 Lógica de Reportes').first().json;
return [{ json: {
  mensaje: r.mensaje, pantalla_nueva: r.pantalla_nueva, paso_nuevo: r.paso_nuevo,
  datos_parciales: r.datos_parciales, resultado: r.resultado
}}];
